INSERT INTO `report_queries` VALUES (3,'data_dictionary_truncate','TRUNCATE data_dictionary;','week',1,NULL,NULL,1,'2022-03-07 14:33:25'),(4,'data_dictionary_insert','INSERT INTO `data_dictionary` SELECT `TABLES`.`table_schema` AS `database_name`, `TABLES`.`TABLE_NAME` AS `table_name`, `TABLES`.`TABLE_COMMENT` AS `table_description`, GROUP_CONCAT(IF(`COLUMNS`.`COLUMN_KEY` LIKE \"PRI\",`COLUMNS`.`COLUMN_NAME`,NULL)) AS `primary_keys`, GROUP_CONCAT(IF(SUBSTRING(`COLUMNS`.`COLUMN_COMMENT`,1,4) LIKE \"link\",`COLUMNS`.`COLUMN_NAME`, NULL)) AS `foreign_keys`, GROUP_CONCAT(IF(SUBSTRING(`COLUMNS`.`COLUMN_COMMENT`,1,4) LIKE \"link\",`COLUMNS`.`COLUMN_COMMENT`,NULL)) AS `linked_tables`, CURRENT_TIMESTAMP `created` FROM `information_schema`.`COLUMNS` INNER JOIN `information_schema`.`TABLES` ON `TABLES`.`table_schema` = `COLUMNS`.`TABLE_SCHEMA` AND `TABLES`.`TABLE_NAME` = `COLUMNS`.`TABLE_NAME` WHERE(`COLUMNS`.`TABLE_SCHEMA` = \"prd_cor_dmo\" OR `COLUMNS`.`TABLE_SCHEMA` = \"tst_cor_dmo\" OR `COLUMNS`.`TABLE_SCHEMA` = \"openemis_core\") AND `TABLES`.`TABLE_NAME` NOT LIKE \"z_%\" GROUP BY `COLUMNS`.`TABLE_NAME`','week',1,NULL,NULL,1,'2022-03-07 14:33:25'),(11,'report_student_assessment_summary_truncate','TRUNCATE report_student_assessment_summary;','week',1,NULL,NULL,1,'2022-04-29 10:29:15'),(13,'summary_institution_student_absences_truncate','TRUNCATE summary_institution_student_absences;','day',0,NULL,NULL,1,'2022-06-13 07:04:27'),(14,'summary_institution_student_absences_insert',' INSERT INTO summary_institution_student_absences SELECT institution_students.institution_id, institutions.code institution_code, institutions.name institution_name, areas.id area_id, areas.code area_code, areas.name area_name, area_administratives.id area_administrative_id, area_administratives.code area_administrative_code, area_administratives.name area_administrative_name, institution_students.student_id, security_users.openemis_no, get_student_default_identity.number default_identity_number, IF(security_users.middle_name IS NOT NULL AND security_users.third_name IS NOT NULL, CONCAT(security_users.first_name,char(32),security_users.middle_name,char(32),security_users.third_name,char(32),security_users.last_name), IF(security_users.middle_name IS NULL AND security_users.third_name IS NULL, CONCAT(security_users.first_name,char(32),security_users.last_name), IF(security_users.middle_name IS NULL AND security_users.third_name IS NOT NULL, CONCAT(security_users.first_name,char(32),security_users.third_name,char(32),security_users.last_name), CONCAT(security_users.first_name,char(32),security_users.middle_name,char(32),security_users.last_name)))) student_name, institution_students.start_date enrol_start_date, institution_students.end_date enrol_end_date, institution_students.academic_period_id, academic_periods.code academic_period_code, academic_periods.name academic_period_name, institution_student_absence_details.education_grade_id, education_grades.code education_grade_code, education_grades.name education_grade_name, institution_student_absence_details.date absent_date, institution_student_absence_days.absent_days, IF(institution_student_absence_details.subject_id = 0,IF(get_period_data.period_name IS NULL,CONCAT(char(80),char(101),char(114),char(105),char(111),char(100),char(32),char(49)), get_period_data.period_name),institution_subjects.name) absence_subject_period, institution_student_absence_details.absence_type_id, absence_types.name absence_type, institution_student_absence_details.student_absence_reason_id, student_absence_reasons.name student_absence_reasons, institution_students.student_status_id, student_statuses.name student_status, NOW() created FROM institution_students INNER JOIN student_statuses ON student_statuses.id = institution_students.student_status_id INNER JOIN institution_student_absence_details ON institution_students.student_id = institution_student_absence_details.student_id AND institution_students.institution_id = institution_student_absence_details.institution_id AND institution_students.education_grade_id = institution_student_absence_details.education_grade_id AND institution_students.academic_period_id = institution_student_absence_details.academic_period_id AND institution_student_absence_details.date BETWEEN institution_students.start_date AND institution_students.end_date INNER JOIN institution_student_absence_days ON institution_student_absence_days.student_id = institution_student_absence_details.student_id AND institution_student_absence_days.institution_id = institution_student_absence_details.institution_id AND institution_student_absence_details.date BETWEEN institution_student_absence_days.start_date AND institution_student_absence_days.end_date INNER JOIN academic_periods ON academic_periods.id = institution_student_absence_details.academic_period_id INNER JOIN institutions ON institutions.id = institution_students.institution_id INNER JOIN security_users ON security_users.id = institution_students.student_id INNER JOIN education_grades ON education_grades.id = institution_students.education_grade_id INNER JOIN absence_types ON absence_types.id = institution_student_absence_details.absence_type_id LEFT JOIN student_absence_reasons ON student_absence_reasons.id = institution_student_absence_details.student_absence_reason_id INNER JOIN areas ON areas.id = institutions.area_id LEFT JOIN area_administratives ON area_administratives.id = institutions.area_administrative_id LEFT JOIN(SELECT student_mark_type_status_grades.education_grade_id, student_mark_type_statuses.academic_period_id, student_mark_type_statuses.date_enabled, student_mark_type_statuses.date_disabled, period period_number, student_attendance_per_day_periods.name period_name FROM student_attendance_mark_types INNER JOIN student_attendance_per_day_periods ON student_attendance_per_day_periods.student_attendance_mark_type_id = student_attendance_mark_types.id INNER JOIN student_mark_type_statuses ON student_mark_type_statuses.student_attendance_mark_type_id = student_attendance_mark_types.id INNER JOIN student_mark_type_status_grades ON student_mark_type_status_grades.student_mark_type_status_id = student_mark_type_statuses.id) get_period_data ON get_period_data.academic_period_id = institution_student_absence_details.academic_period_id AND get_period_data.education_grade_id = institution_student_absence_details.education_grade_id AND institution_student_absence_details.date BETWEEN get_period_data.date_enabled AND get_period_data.date_disabled LEFT JOIN institution_subjects ON institution_subjects.id = institution_student_absence_details.subject_id LEFT JOIN (SELECT user_identities.number, user_identities.security_user_id FROM user_identities INNER JOIN identity_types ON identity_types.id = user_identities.identity_type_id WHERE identity_types.default = 1) get_student_default_identity ON get_student_default_identity.security_user_id = institution_student_absence_details.student_id ORDER BY institution_student_absence_details.student_id ASC, institution_students.academic_period_id ASC;','day',0,NULL,NULL,1,'2022-06-13 07:04:27'),(15,'get_total_student_subjects_create','CREATE TABLE IF NOT EXISTS `get_total_student_subjects`( `academic_period_id` INT(10) NOT NULL, `institution_id` INT(10) NOT NULL, `education_grade_id` INT(10) NOT NULL, `institution_class_id` INT(10) NOT NULL, `education_subject_id` INT(10) NOT NULL, `count_students` INT(10) NOT NULL, INDEX(`academic_period_id`, `institution_id`, `education_grade_id`, `education_subject_id`)) ENGINE = InnoDB DEFAULT CHARSET=utf8;','week',1,NULL,NULL,1,'2022-07-30 06:59:13'),(16,'get_total_student_subjects_insert','INSERT INTO get_total_student_subjects SELECT institution_subject_students.academic_period_id, institution_subject_students.institution_id, institution_subject_students.education_grade_id, institution_class_students.institution_class_id, institution_subject_students.education_subject_id, count(*) AS count_students FROM institution_subject_students INNER JOIN academic_periods ON academic_periods.id = academic_period_id INNER JOIN institution_students ON institution_students.student_id = institution_subject_students.student_id AND institution_students.education_grade_id = institution_subject_students.education_grade_id AND institution_students.academic_period_id = institution_subject_students.academic_period_id AND institution_students.student_status_id = institution_subject_students.student_status_id AND institution_students.institution_id = institution_subject_students.institution_id INNER JOIN institution_class_students ON institution_students.student_id = institution_class_students.student_id AND institution_students.education_grade_id = institution_class_students.education_grade_id AND institution_students.academic_period_id = institution_class_students.academic_period_id AND institution_students.student_status_id = institution_class_students.student_status_id AND institution_students.institution_id = institution_class_students.institution_id WHERE institution_students.student_status_id = 1 AND academic_periods.current = 1 GROUP BY institution_subject_students.academic_period_id, institution_subject_students.institution_id, institution_subject_students.education_grade_id, institution_class_students.institution_class_id, institution_subject_students.education_subject_id;','week',1,NULL,NULL,1,'2022-07-30 06:59:13'),(17,'get_grouped_students_subjects_create','CREATE TABLE IF NOT EXISTS `get_grouped_students_subjects`( `student_id` int(10) NOT NULL, `institution_id` int(10) NOT NULL, `academic_period_id` int(10) NOT NULL, `institution_class_id` int(10) NOT NULL, `education_subject_id` int(10) NOT NULL, `assessment_id` int(10) NOT NULL, `assessment_period_id` int(10) NOT NULL, `academic_term` varchar(100) DEFAULT NULL, INDEX(`student_id`, `institution_id`, `institution_class_id`, `academic_period_id`, `education_subject_id`, `assessment_id`, `assessment_period_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;','week',1,NULL,NULL,1,'2022-07-30 06:59:13'),(18,'get_grouped_students_subjects_insert','INSERT INTO get_grouped_students_subjects SELECT assessment_item_results.student_id, assessment_item_results.institution_id, assessment_item_results.academic_period_id, institution_class_id, education_subject_id, assessment_item_results.assessment_id, assessment_period_id, academic_term FROM assessment_item_results INNER JOIN assessment_periods ON assessment_periods.assessment_id = assessment_item_results.assessment_id INNER JOIN academic_periods ON academic_periods.id = assessment_item_results.academic_period_id INNER JOIN institution_students ON institution_students.student_id = assessment_item_results.student_id AND institution_students.education_grade_id = assessment_item_results.education_grade_id AND institution_students.academic_period_id = assessment_item_results.academic_period_id AND institution_students.institution_id = assessment_item_results.institution_id INNER JOIN institution_class_students ON institution_students.student_id = institution_class_students.student_id AND institution_students.education_grade_id = institution_class_students.education_grade_id AND institution_students.academic_period_id = institution_class_students.academic_period_id AND institution_students.student_status_id = institution_class_students.student_status_id AND institution_students.institution_id = institution_class_students.institution_id WHERE assessment_item_results.marks IS NOT NULL AND institution_students.student_status_id = 1 AND academic_periods.current = 1 GROUP BY assessment_item_results.student_id, assessment_item_results.institution_id, assessment_item_results.academic_period_id, assessment_item_results.assessment_id, assessment_item_results.education_grade_id, institution_class_id, assessment_item_results.assessment_period_id, education_subject_id;','week',1,NULL,NULL,1,'2022-07-30 06:59:13'),(19,'get_marked_students_create','CREATE TABLE IF NOT EXISTS `get_marked_students` ( `academic_period_id` int(10) NOT NULL, `assessment_id` int(10) NOT NULL, `assessment_period_id` int(10) NOT NULL, `academic_term` varchar(100) DEFAULT NULL, `institution_id` int(10) NOT NULL, `institution_class_id` int(10) NOT NULL, `education_subject_id` int(10) NOT NULL, `count_marked_students` int(10) NOT NULL, INDEX(`academic_period_id`, `assessment_id`, `assessment_period_id`, `institution_id`, `education_subject_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;','week',1,NULL,NULL,1,'2022-07-30 06:59:13'),(20,'get_marked_students_insert','INSERT INTO get_marked_students SELECT academic_period_id, assessment_id, assessment_period_id, academic_term, institution_id, institution_class_id, education_subject_id, count(*) count_marked_students FROM get_grouped_students_subjects GROUP BY institution_id, academic_period_id, assessment_period_id, institution_class_id, education_subject_id;','week',1,NULL,NULL,1,'2022-07-30 06:59:13'),(21,'summary_assessment_item_results_truncate','TRUNCATE summary_assessment_item_results;','week',1,NULL,NULL,1,'2022-07-30 06:59:13'),(22,'summary_assessment_item_results_insert','INSERT INTO summary_assessment_item_results SELECT academic_periods.id academic_period_id, academic_periods.name academic_period_name, get_assessments.assessment_id, assessment_code, assessment_name, assessment_periods.id assessment_period_id, assessment_periods.name assessment_period_name, get_assessments.academic_term, subject_id, subject_name, education_grades.id education_grade_id, education_grades.name education_grade, institutions.id institution_id, institutions.code institution_code, institutions.name institution_name, institution_providers.id institution_provider_id, institution_providers.name institution_provider, area_edu.area_id area_id, area_edu.area_name area, get_total_student_subjects.institution_class_id, institution_classes.name institution_class_name, IF(count_students IS NULL,0,count_students) count_students, IF(count_marked_students IS NULL,0,count_marked_students) count_marked_students, IF(count_students IS NULL,0, IF(count_marked_students IS NULL, count_students, count_students-count_marked_students)) missing_marks, CURRENT_TIMESTAMP FROM (SELECT assessments.id assessment_id, assessments.code assessment_code, assessments.name assessment_name, assessments.academic_period_id, assessments.education_grade_id, assessment_periods.id assessment_period_id, assessment_periods.academic_term, education_subjects.id subject_id, education_subjects.code subject_code, education_subjects.name subject_name FROM assessments INNER JOIN assessment_periods ON assessments.id = assessment_periods.assessment_id INNER JOIN assessment_items ON assessment_items.assessment_id = assessments.id INNER JOIN education_subjects ON assessment_items.education_subject_id = education_subjects.id) get_assessments LEFT JOIN assessment_periods ON assessment_periods.id = get_assessments.assessment_period_id INNER JOIN academic_periods ON academic_periods.id = get_assessments.academic_period_id LEFT JOIN institution_grades ON institution_grades.education_grade_id = get_assessments.education_grade_id INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN institution_providers ON institution_providers.id = institutions.institution_provider_id LEFT JOIN (SELECT areas.id AS area_id, areas.name AS area_name FROM areas INNER JOIN area_levels ON area_levels.id = areas.area_level_id) AS area_edu ON institutions.area_id = area_edu.area_id INNER JOIN education_grades ON education_grades.id = get_assessments.education_grade_id LEFT JOIN get_total_student_subjects ON get_total_student_subjects.institution_id = institutions.id AND get_total_student_subjects.academic_period_id = get_assessments.academic_period_id AND get_total_student_subjects.education_grade_id = get_assessments.education_grade_id AND get_total_student_subjects.education_subject_id = get_assessments.subject_id LEFT JOIN get_marked_students ON get_marked_students.institution_id = institutions.id AND get_marked_students.assessment_id = get_assessments.assessment_id AND get_marked_students.assessment_period_id = assessment_periods.id AND get_marked_students.academic_period_id = academic_periods.id AND get_marked_students.education_subject_id = get_assessments.subject_id AND get_marked_students.institution_class_id=get_total_student_subjects.institution_class_id LEFT JOIN institution_classes ON institution_classes.id = get_total_student_subjects.institution_class_id WHERE area_edu.area_id IS NOT NULL AND institutions.id IS NOT NULL AND education_grades.id IS NOT NULL AND get_assessments.assessment_id IS NOT NULL AND assessment_periods.id IS NOT NULL AND academic_periods.current = 1 ORDER BY academic_periods.id ASC, institutions.id ASC, assessment_periods.id ASC;','week',1,NULL,NULL,1,'2022-07-30 06:59:13'),(23,'drop_summary_assessment_item_results_tmp','DROP TABLE IF EXISTS `get_grouped_students_subjects`, `get_marked_students`, `get_total_student_subjects`;','week',1,NULL,NULL,1,'2022-07-30 06:59:13'),(24,'system_errors_truncate','TRUNCATE system_errors;','week',1,NULL,NULL,1,'2022-08-09 10:26:20'),(25,'report_student_assessment_summary_insert','INSERT INTO report_student_assessment_summary SELECT academic_periods.id academic_period_id ,academic_periods.code academic_period_code ,academic_periods.name academic_period_name ,areas.id area_id ,areas.code area_code ,areas.name area_name ,institutions.id institution_id ,institutions.code institution_code ,institutions.name institution_name ,education_grades.id education_grade_id ,education_grades.code education_grade_code ,education_grades.name education_grade_name ,institution_classes.id institution_class_id ,institution_classes.name institution_class_name ,homeroom_teacher.id homeroom_teacher_id ,CONCAT(homeroom_teacher.first_name,homeroom_teacher.last_name) homeroom_teacher_name ,education_subjects.id education_subject_id ,education_subjects.code education_subject_code ,education_subjects.name education_subject_name ,assessment_items.weight subject_weight ,assessments.id assessment_id ,assessments.code assessment_code ,assessments.name assessment_name ,assessment_periods.id assessment_period_id ,assessment_periods.code assessment_period_code ,assessment_periods.name assessment_period_name ,assessment_periods.academic_term ,assessment_periods.weight period_weight ,students.id student_id ,CONCAT(students.first_name,students.last_name) student_name ,assessment_item_results.marks latest_mark ,get_total_student_mark.total_mark ,get_avg_student_mark.average_mark ,get_instituion_average_mark.instituion_average_mark ,get_area_average_mark.area_average_mark ,NOW() created FROM assessment_item_results INNER JOIN institutions ON institutions.id = assessment_item_results.institution_id INNER JOIN areas ON areas.id = institutions.area_id INNER JOIN education_grades ON education_grades.id = assessment_item_results.education_grade_id LEFT JOIN institution_classes ON institution_classes.id = assessment_item_results.institution_classes_id AND institution_classes.institution_id = institutions.id INNER JOIN education_subjects ON education_subjects.id = assessment_item_results.education_subject_id INNER JOIN assessments ON assessments.id = assessment_item_results.assessment_id AND assessments.academic_period_id = assessment_item_results.academic_period_id AND assessments.education_grade_id = assessment_item_results.education_grade_id INNER JOIN assessment_items ON assessment_items.assessment_id = assessments.id AND assessment_items.education_subject_id = assessment_item_results.education_subject_id INNER JOIN assessment_periods ON assessment_periods.id = assessment_item_results.assessment_period_id INNER JOIN security_users students ON students.id = assessment_item_results.student_id LEFT JOIN security_users homeroom_teacher ON institution_classes.staff_id = homeroom_teacher.id INNER JOIN( SELECT assessment_item_results.student_id ,assessment_item_results.assessment_period_id ,assessment_item_results.education_subject_id ,MAX(assessment_item_results.created) latest_created FROM assessment_item_results GROUP BY assessment_item_results.student_id ,assessment_item_results.assessment_period_id ,assessment_item_results.education_subject_id) latest_data ON latest_data.student_id = assessment_item_results.student_id AND latest_data.assessment_period_id = assessment_item_results.assessment_period_id AND latest_data.education_subject_id = assessment_item_results.education_subject_id AND latest_data.latest_created = assessment_item_results.created INNER JOIN academic_periods ON academic_periods.id = assessment_item_results.academic_period_id LEFT JOIN ( SELECT institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,institution_subject_students.institution_class_id ,institution_subject_students.education_grade_id ,institution_subject_students.student_id ,institution_subject_students.education_subject_id ,ROUND(AVG(institution_subject_students.total_mark),2) total_mark FROM institution_subject_students GROUP BY institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,institution_subject_students.institution_class_id ,institution_subject_students.education_grade_id ,institution_subject_students.student_id ,institution_subject_students.education_subject_id ) get_total_student_mark ON get_total_student_mark.academic_period_id = assessment_item_results.academic_period_id AND get_total_student_mark.institution_id = assessment_item_results.institution_id AND get_total_student_mark.institution_class_id = assessment_item_results.institution_classes_id AND get_total_student_mark.education_grade_id = assessment_item_results.education_grade_id AND get_total_student_mark.student_id = assessment_item_results.student_id AND get_total_student_mark.education_subject_id = assessment_item_results.education_subject_id LEFT JOIN ( SELECT institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,institution_subject_students.institution_class_id ,institution_subject_students.education_grade_id ,institution_subject_students.student_id ,ROUND(AVG(institution_subject_students.total_mark),2) average_mark FROM institution_subject_students GROUP BY institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,institution_subject_students.institution_class_id ,institution_subject_students.education_grade_id ,institution_subject_students.student_id ) get_avg_student_mark ON get_avg_student_mark.academic_period_id = assessment_item_results.academic_period_id AND get_avg_student_mark.institution_id = assessment_item_results.institution_id AND get_avg_student_mark.institution_class_id = assessment_item_results.institution_classes_id AND get_avg_student_mark.education_grade_id = assessment_item_results.education_grade_id AND get_avg_student_mark.student_id = assessment_item_results.student_id LEFT JOIN ( SELECT institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,ROUND(AVG(institution_subject_students.total_mark),2) instituion_average_mark FROM institution_subject_students GROUP BY institution_subject_students.academic_period_id ,institution_subject_students.institution_id ) get_instituion_average_mark ON get_instituion_average_mark.academic_period_id = assessment_item_results.academic_period_id AND get_instituion_average_mark.institution_id = assessment_item_results.institution_id LEFT JOIN ( SELECT institution_subject_students.academic_period_id ,institutions.area_id ,ROUND(AVG(institution_subject_students.total_mark),2) area_average_mark FROM institution_subject_students INNER JOIN institutions ON institutions.id = institution_subject_students.institution_id GROUP BY institution_subject_students.academic_period_id ,institutions.area_id ) get_area_average_mark ON get_area_average_mark.academic_period_id = assessment_item_results.academic_period_id AND get_area_average_mark.area_id = areas.id','week',1,NULL,NULL,1,'2022-11-01 01:09:25'),(26,'summary_institutions_truncate','TRUNCATE summary_institutions;','week',1,NULL,NULL,1,'2022-11-21 07:22:05'),(27,'summary_institutions_insert','INSERT INTO summary_institutions (academic_period_id, academic_period_name, institution_id, institution_code, total_grades, total_classes, total_lands, total_land_size, total_buildings, total_building_sizes, total_floors, total_floor_sizes, total_rooms, total_room_sizes, total_room_classrooms, total_room_classroom_sizes, total_students, total_students_female, total_students_male, total_staff_teaching, total_staff_teaching_female, total_staff_teaching_male, total_staff_non_teaching, total_staff_non_teaching_female, total_staff_non_teaching_male) SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institutions.id institution_id ,institutions.code institution_code ,IFNULL(grade_count.total_grades, 0) total_grades ,IFNULL(class_count.total_classes, 0) total_classes ,IFNULL(land_info.total_lands, 0) total_lands ,IFNULL(land_info.total_land_size, 0) total_land_size ,IFNULL(building_info.total_buildings, 0) total_buildings ,IFNULL(building_info.total_building_sizes, 0) total_building_sizes ,IFNULL(floor_info.total_floors, 0) total_floors ,IFNULL(floor_info.total_floor_sizes, 0) total_floor_sizes ,IFNULL(room_info.total_rooms, 0) total_rooms ,IFNULL(room_info.total_room_sizes, 0) total_room_sizes ,IFNULL(classroom_info.total_room_classrooms, 0) total_room_classrooms ,IFNULL(classroom_info.total_room_classroom_sizes, 0) total_room_classroom_sizes ,IFNULL(student_info.total_students, 0) total_students ,IFNULL(student_info.total_students_female, 0) total_students_female ,IFNULL(student_info.total_students_male, 0) total_students_male ,IFNULL(teaching_staff_info.total_staff_teaching, 0) total_staff_teaching ,IFNULL(teaching_staff_info.total_staff_teaching_female, 0) total_staff_teaching_female ,IFNULL(teaching_staff_info.total_staff_teaching_male, 0) total_staff_teaching_male ,IFNULL(non_teaching_staff_info.total_staff_non_teaching, 0) total_staff_non_teaching ,IFNULL(non_teaching_staff_info.total_staff_non_teaching_female, 0) total_staff_non_teaching_female ,IFNULL(non_teaching_staff_info.total_staff_non_teaching_male, 0) total_staff_non_teaching_male FROM institutions INNER JOIN academic_periods ON (((institutions.date_closed IS NOT NULL AND institutions.date_opened <= academic_periods.start_date AND institutions.date_closed >= academic_periods.start_date) OR (institutions.date_closed IS NOT NULL AND institutions.date_opened <= academic_periods.end_date AND institutions.date_closed >= academic_periods.end_date) OR (institutions.date_closed IS NOT NULL AND institutions.date_opened >= academic_periods.start_date AND institutions.date_closed <= academic_periods.end_date)) OR (institutions.date_closed IS NULL AND institutions.date_opened <= academic_periods.end_date)) LEFT JOIN ( SELECT academic_periods.id academic_period_id ,institution_grades.institution_id ,COUNT(DISTINCT(education_grades.id)) total_grades FROM institution_grades INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id GROUP BY institution_grades.institution_id ,academic_periods.id) grade_count ON grade_count.institution_id = institutions.id AND grade_count.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_classes.academic_period_id ,institution_classes.institution_id ,COUNT(DISTINCT(institution_classes.id)) total_classes FROM institution_classes GROUP BY institution_classes.institution_id ,institution_classes.academic_period_id ) class_count ON class_count.institution_id = institutions.id AND class_count.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_lands.academic_period_id ,institution_lands.institution_id ,COUNT(DISTINCT(institution_lands.id)) total_lands ,SUM(IFNULL(institution_lands.area, 0)) total_land_size FROM institution_lands GROUP BY institution_lands.institution_id ,institution_lands.academic_period_id ) land_info ON land_info.institution_id = institutions.id AND land_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_buildings.academic_period_id ,institution_buildings.institution_id ,COUNT(DISTINCT(institution_buildings.id)) total_buildings ,SUM(IFNULL(institution_buildings.area, 0)) total_building_sizes FROM institution_buildings GROUP BY institution_buildings.institution_id ,institution_buildings.academic_period_id ) building_info ON building_info.institution_id = institutions.id AND building_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_floors.academic_period_id ,institution_floors.institution_id ,COUNT(DISTINCT(institution_floors.id)) total_floors ,SUM(IFNULL(institution_floors.area, 0)) total_floor_sizes FROM institution_floors GROUP BY institution_floors.institution_id ,institution_floors.academic_period_id ) floor_info ON floor_info.institution_id = institutions.id AND floor_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_rooms.academic_period_id ,institution_rooms.institution_id ,COUNT(DISTINCT(institution_rooms.id)) total_rooms ,SUM(IFNULL(institution_rooms.area, 0)) total_room_sizes FROM institution_rooms GROUP BY institution_rooms.institution_id ,institution_rooms.academic_period_id ) room_info ON room_info.institution_id = institutions.id AND room_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_rooms.academic_period_id ,institution_rooms.institution_id ,COUNT(DISTINCT(institution_rooms.id)) total_room_classrooms ,SUM(IFNULL(institution_rooms.area, 0)) total_room_classroom_sizes FROM institution_rooms INNER JOIN room_types ON room_types.id = institution_rooms.room_type_id WHERE room_types.classification = 1 GROUP BY institution_rooms.institution_id ,institution_rooms.academic_period_id ) classroom_info ON classroom_info.institution_id = institutions.id AND classroom_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_students.academic_period_id ,institution_students.institution_id ,SUM(CASE WHEN security_users.gender_id IN (1, 2) THEN 1 ELSE 0 END) total_students ,SUM(CASE WHEN security_users.gender_id = 2 THEN 1 ELSE 0 END) total_students_female ,SUM(CASE WHEN security_users.gender_id = 1 THEN 1 ELSE 0 END) total_students_male FROM institution_students INNER JOIN security_users ON security_users.id = institution_students.student_id INNER JOIN academic_periods ON academic_periods.id = institution_students.academic_period_id WHERE IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) GROUP BY institution_students.institution_id ,institution_students.academic_period_id ) student_info ON student_info.institution_id = institutions.id AND student_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT academic_periods.id academic_period_id ,institution_staff.institution_id ,SUM(CASE WHEN security_users.gender_id IN (1, 2) THEN 1 ELSE 0 END) total_staff_teaching ,SUM(CASE WHEN security_users.gender_id = 2 THEN 1 ELSE 0 END) total_staff_teaching_female ,SUM(CASE WHEN security_users.gender_id = 1 THEN 1 ELSE 0 END) total_staff_teaching_male FROM institution_staff INNER JOIN security_users ON security_users.id = institution_staff.staff_id INNER JOIN institution_positions ON institution_positions.id = institution_staff.institution_position_id AND institution_positions.institution_id = institution_staff.institution_id INNER JOIN staff_position_titles ON staff_position_titles.id = institution_positions.staff_position_title_id INNER JOIN academic_periods ON (((institution_staff.end_date IS NOT NULL AND institution_staff.start_date <= academic_periods.start_date AND institution_staff.end_date >= academic_periods.start_date) OR (institution_staff.end_date IS NOT NULL AND institution_staff.start_date <= academic_periods.end_date AND institution_staff.end_date >= academic_periods.end_date) OR (institution_staff.end_date IS NOT NULL AND institution_staff.start_date >= academic_periods.start_date AND institution_staff.end_date <= academic_periods.end_date)) OR (institution_staff.end_date IS NULL AND institution_staff.start_date <= academic_periods.end_date)) WHERE institution_staff.staff_status_id = 1 AND staff_position_titles.type = 1 GROUP BY institution_staff.institution_id ,academic_periods.id ) teaching_staff_info ON teaching_staff_info.institution_id = institutions.id AND teaching_staff_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT academic_periods.id academic_period_id ,institution_staff.institution_id ,SUM(CASE WHEN security_users.gender_id IN (1, 2) THEN 1 ELSE 0 END) total_staff_non_teaching ,SUM(CASE WHEN security_users.gender_id = 2 THEN 1 ELSE 0 END) total_staff_non_teaching_female ,SUM(CASE WHEN security_users.gender_id = 1 THEN 1 ELSE 0 END) total_staff_non_teaching_male FROM institution_staff INNER JOIN security_users ON security_users.id = institution_staff.staff_id INNER JOIN institution_positions ON institution_positions.id = institution_staff.institution_position_id AND institution_positions.institution_id = institution_staff.institution_id INNER JOIN staff_position_titles ON staff_position_titles.id = institution_positions.staff_position_title_id INNER JOIN academic_periods ON (((institution_staff.end_date IS NOT NULL AND institution_staff.start_date <= academic_periods.start_date AND institution_staff.end_date >= academic_periods.start_date) OR (institution_staff.end_date IS NOT NULL AND institution_staff.start_date <= academic_periods.end_date AND institution_staff.end_date >= academic_periods.end_date) OR (institution_staff.end_date IS NOT NULL AND institution_staff.start_date >= academic_periods.start_date AND institution_staff.end_date <= academic_periods.end_date)) OR (institution_staff.end_date IS NULL AND institution_staff.start_date <= academic_periods.end_date)) WHERE institution_staff.staff_status_id = 1 AND staff_position_titles.type = 0 GROUP BY institution_staff.institution_id ,academic_periods.id ) non_teaching_staff_info ON non_teaching_staff_info.institution_id = institutions.id AND non_teaching_staff_info.academic_period_id = academic_periods.id;','week',1,NULL,NULL,1,'2022-11-21 07:22:05'),(28,'summary_institution_grades_truncate','TRUNCATE summary_institution_grades;','week',1,NULL,NULL,1,'2022-11-21 07:22:05'),(29,'summary_institution_grades_insert','INSERT INTO summary_institution_grades (academic_period_id, academic_period_name, institution_id, institution_code, grade_id, grade_name, total_classes, total_classes_female, total_classes_male, total_classes_mixed, total_students, total_students_female, total_students_male, total_home_room_teachers, total_secondary_teachers) SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institutions.id institution_id ,institutions.code institution_code ,education_grades.id grade_id ,education_grades.name grade_name ,IFNULL(SUM(classes_info.total_classes), 0) total_classes ,IFNULL(SUM(classes_info.female_classes), 0) total_classes_female ,IFNULL(SUM(classes_info.male_classes), 0) total_classes_male ,IFNULL(SUM(classes_info.mixed_classes), 0) total_classes_mixed ,IFNULL(SUM(student_info.total_students), 0) total_students ,IFNULL(SUM(student_info.total_students_female), 0) total_students_female ,IFNULL(SUM(student_info.total_students_male), 0) total_students_male ,IFNULL(SUM(classes_info.total_home_room_teachers), 0) total_home_room_teachers ,IFNULL(SUM(classes_info.total_secondary_teachers), 0) total_secondary_teachers FROM institution_grades INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id LEFT JOIN ( SELECT academic_periods.id academic_period_id ,institution_classes.institution_id ,education_grades.id education_grade_id ,SUM(CASE WHEN institution_classes.total_male_students > 0 AND institution_classes.total_female_students = 0 THEN 1 ELSE 0 END) male_classes ,SUM(CASE WHEN institution_classes.total_male_students = 0 AND institution_classes.total_female_students > 0 THEN 1 ELSE 0 END) female_classes ,SUM(CASE WHEN IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), (institution_classes.total_male_students > 0 AND institution_classes.total_female_students > 0), ((institution_classes.total_male_students > 0 AND institution_classes.total_female_students > 0) OR (institution_classes.total_male_students = 0 AND institution_classes.total_female_students = 0))) THEN 1 ELSE 0 END) mixed_classes ,COUNT(institution_classes.id) total_classes ,COUNT(DISTINCT(CASE WHEN institution_classes.staff_id != 0 THEN institution_classes.staff_id END)) total_home_room_teachers ,COUNT(DISTINCT(institution_classes_secondary_staff.secondary_staff_id)) total_secondary_teachers FROM institution_class_grades INNER JOIN institution_classes ON institution_classes.id = institution_class_grades.institution_class_id INNER JOIN education_grades ON education_grades.id = institution_class_grades.education_grade_id INNER JOIN academic_periods ON academic_periods.id = institution_classes.academic_period_id LEFT JOIN institution_classes_secondary_staff ON institution_classes_secondary_staff.institution_class_id = institution_classes.id GROUP BY academic_periods.id ,institution_classes.institution_id ,institution_class_grades.education_grade_id) classes_info ON classes_info.academic_period_id = academic_periods.id AND classes_info.institution_id = institutions.id AND classes_info.education_grade_id = education_grades.id LEFT JOIN ( SELECT institution_students.academic_period_id ,institution_students.institution_id ,institution_students.education_grade_id ,SUM(CASE WHEN security_users.gender_id IN (1,2) AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students ,SUM(CASE WHEN security_users.gender_id = 2 AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students_female ,SUM(CASE WHEN security_users.gender_id = 1 AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students_male FROM institution_students INNER JOIN security_users ON security_users.id = institution_students.student_id INNER JOIN academic_periods ON academic_periods.id = institution_students.academic_period_id GROUP BY institution_students.academic_period_id ,institution_students.institution_id ,institution_students.education_grade_id ) student_info ON student_info.academic_period_id = academic_periods.id AND student_info.institution_id = institutions.id AND student_info.education_grade_id = education_grades.id GROUP BY academic_periods.id ,institution_grades.institution_id ,education_grades.id;','week',1,NULL,NULL,1,'2022-11-21 07:22:05'),(30,'summary_institution_room_types_truncate','TRUNCATE summary_institution_room_types;','week',1,NULL,NULL,1,'2022-11-21 07:22:05'),(31,'summary_institution_room_types_insert','INSERT INTO summary_institution_room_types (academic_period_id, academic_period_name, institution_id, institution_code, room_type, total_rooms) SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institutions.id institution_id ,institutions.code institution_code ,room_types.name room_type ,COUNT(DISTINCT(institution_rooms.id)) total_rooms FROM institution_rooms INNER JOIN room_types ON room_types.id = institution_rooms.room_type_id INNER JOIN institutions ON institutions.id = institution_rooms.institution_id INNER JOIN academic_periods ON academic_periods.id = institution_rooms.academic_period_id GROUP BY academic_periods.id ,institutions.id ,room_types.id;','week',1,NULL,NULL,1,'2022-11-21 07:22:05'),(38,'clear_otp','DELETE FROM security_user_codes WHERE created < DATE_SUB(NOW(), INTERVAL `1` HOUR);','hour',1,NULL,NULL,1,'2023-01-06 09:42:45'),(39,'summary_programme_sector_genders_truncate','TRUNCATE summary_programme_sector_genders;','week',1,NULL,NULL,1,'2023-01-12 07:54:34'),(40,'summary_programme_sector_genders_insert','INSERT INTO summary_programme_sector_genders (academic_period_id, academic_period_name, institution_sector_id, institution_sector_name, education_system_id, education_system_name, education_level_isced_id, education_level_isced_name, educ