--
-- Table structure for table `scholarship_application_attachments`
--

DROP TABLE IF EXISTS `scholarship_application_attachments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `scholarship_application_attachments` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_name` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_content` longblob NOT NULL,
  `scholarship_attachment_type_id` int NOT NULL COMMENT 'links to scholarship_attachment_types.id',
  `applicant_id` int NOT NULL COMMENT 'links to security_users.id',
  `scholarship_id` int NOT NULL COMMENT 'links to scholarships.id',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `scholarship_attachment_type_id` (`scholarship_attachment_type_id`),
  KEY `applicant_id` (`applicant_id`),
  KEY `scholarship_id` (`scholarship_id`),
  KEY `modified_user_id` (`modified_user_id`),
  KEY `created_user_id` (`created_user_id`),
  CONSTRAINT `schol_appli_attac_fk_app_id` FOREIGN KEY (`applicant_id`) REFERENCES `security_users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `schol_appli_attac_fk_schol_attac_type_id` FOREIGN KEY (`scholarship_attachment_type_id`) REFERENCES `scholarship_attachment_types` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `schol_appli_attac_fk_schol_id` FOREIGN KEY (`scholarship_id`) REFERENCES `scholarships` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='This table contains the list of attachments linked to specific scholarship application';
/*!40101 SET character_set_client = @saved_cs_client */;

